import{_ as i,o as t,c as l,ae as e}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"テンプレート明細インポート（CSV）","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/guide/01-template-bill-import-guide.md","filePath":"v1/ja/guide/01-template-bill-import-guide.md"}'),r={name:"v1/ja/guide/01-template-bill-import-guide.md"};function s(o,a,d,h,n,c){return t(),l("div",null,[...a[0]||(a[0]=[e(`<h1 id="テンプレート明細インポート-csv" tabindex="-1">テンプレート明細インポート（CSV） <a class="header-anchor" href="#テンプレート明細インポート-csv" aria-label="Permalink to &quot;テンプレート明細インポート（CSV）&quot;">​</a></h1><h2 id="📋-概要" tabindex="-1">📋 概要 <a class="header-anchor" href="#📋-概要" aria-label="Permalink to &quot;📋 概要&quot;">​</a></h2><p>Koala では、外部ファイルから明細データをインポートして、過去の記録をまとめて取り込めます。現在、以下の方法に対応しています。</p><ul><li><strong>テンプレートファイル</strong>：標準フォーマットの CSV を取り込み</li><li><strong>WeChat</strong>：WeChat から書き出した明細ファイルを取り込み</li><li><strong>Alipay</strong>：Alipay から書き出した明細ファイルを取り込み</li><li><strong>Pixiu</strong>：Pixiu から書き出した CSV を取り込み</li><li><strong>iCost</strong>：iCost から書き出した Excel を取り込み</li></ul><hr><h2 id="📁-対応ファイル形式" tabindex="-1">📁 対応ファイル形式 <a class="header-anchor" href="#📁-対応ファイル形式" aria-label="Permalink to &quot;📁 対応ファイル形式&quot;">​</a></h2><ul><li><strong>CSV</strong>（<code>.csv</code>）：Alipay、Pixiu、テンプレート</li><li><strong>Excel</strong>（<code>.xlsx</code> / <code>.xls</code>）：WeChat、iCost</li></ul><hr><h2 id="🚀-クイックスタート" tabindex="-1">🚀 クイックスタート <a class="header-anchor" href="#🚀-クイックスタート" aria-label="Permalink to &quot;🚀 クイックスタート&quot;">​</a></h2><h3 id="手順-1-インポート画面を開く" tabindex="-1">手順 1：インポート画面を開く <a class="header-anchor" href="#手順-1-インポート画面を開く" aria-label="Permalink to &quot;手順 1：インポート画面を開く&quot;">​</a></h3><ol><li>Koala を開く</li><li>画面下の <strong>「設定」</strong> をタップ</li><li>設定画面で <strong>「明細インポート」</strong> を探す</li><li>明細インポート画面に入る</li></ol><h3 id="手順-2-インポート元を選ぶ" tabindex="-1">手順 2：インポート元を選ぶ <a class="header-anchor" href="#手順-2-インポート元を選ぶ" aria-label="Permalink to &quot;手順 2：インポート元を選ぶ&quot;">​</a></h3><p>インポート画面で、明細の出所（インポート元）を選びます。</p><ul><li><strong>テンプレート</strong>：標準フォーマットの CSV</li><li><strong>WeChat</strong>：WeChat から書き出したファイル</li><li><strong>Alipay</strong>：Alipay から書き出したファイル</li><li><strong>Pixiu</strong>：Pixiu から書き出したファイル</li><li><strong>iCost</strong>：iCost から書き出したファイル</li></ul><blockquote><p>⚠️ <strong>重要</strong>：インポート元を間違えると解析に失敗したり、項目がずれて取り込まれることがあります。</p></blockquote><h3 id="手順-3-ファイルを選択" tabindex="-1">手順 3：ファイルを選択 <a class="header-anchor" href="#手順-3-ファイルを選択" aria-label="Permalink to &quot;手順 3：ファイルを選択&quot;">​</a></h3><ol><li><strong>「ファイルパス」</strong> をタップ</li><li>ファイル選択画面で、取り込みたいファイルを選ぶ</li><li>ファイル名が表示されていることを確認</li></ol><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>ファイルは端末内に保存されている必要があります（ファイルアプリから参照できる場所）</li><li>ファイル形式（CSV / Excel）が正しいことを確認してください</li><li>ファイルが破損している場合は再書き出しをお試しください</li></ul></blockquote><h3 id="手順-4-帳本-ledger-を関連付ける" tabindex="-1">手順 4：帳本（Ledger）を関連付ける <a class="header-anchor" href="#手順-4-帳本-ledger-を関連付ける" aria-label="Permalink to &quot;手順 4：帳本（Ledger）を関連付ける&quot;">​</a></h3><ol><li><strong>「関連付け帳本」</strong> をタップ</li><li>取り込み先の帳本を選ぶ</li></ol><blockquote><p>💡 ヒント：帳本が 1 つしかない場合、自動的に既定の帳本が選ばれることがあります。</p></blockquote><h3 id="手順-5-解析-プレビューへ" tabindex="-1">手順 5：解析（プレビューへ） <a class="header-anchor" href="#手順-5-解析-プレビューへ" aria-label="Permalink to &quot;手順 5：解析（プレビューへ）&quot;">​</a></h3><ol><li>右上の <strong>「解析」</strong> をタップ</li><li>解析が完了するとプレビュー画面に移動します</li></ol><blockquote><p>⚠️ <strong>解析に失敗する場合</strong>：</p><ul><li>ファイル形式が正しいか</li><li>インポート元の選択が正しいか</li><li>ファイルが破損していないか</li><li>再書き出ししたファイルで再度お試しください</li></ul></blockquote><h3 id="手順-6-プレビューと編集" tabindex="-1">手順 6：プレビューと編集 <a class="header-anchor" href="#手順-6-プレビューと編集" aria-label="Permalink to &quot;手順 6：プレビューと編集&quot;">​</a></h3><p>プレビュー画面では以下ができます。</p><ul><li>明細を日付ごとに確認</li><li>1 件ずつ編集（カテゴリ、金額、日時、口座、タグ、メモなど）</li><li>長押しで無効な明細を削除</li><li>無効な明細をまとめてスキップ</li></ul><blockquote><p>📝 推奨：取り込み前に必ずプレビューで内容を確認し、必要ならカテゴリや口座を調整してください。</p></blockquote><h3 id="手順-7-インポート実行" tabindex="-1">手順 7：インポート実行 <a class="header-anchor" href="#手順-7-インポート実行" aria-label="Permalink to &quot;手順 7：インポート実行&quot;">​</a></h3><ol><li>内容を確認したら <strong>「インポート」</strong> をタップ</li><li>完了まで待つ</li></ol><hr><h2 id="📝-テンプレート-csv-フォーマット" tabindex="-1">📝 テンプレート CSV フォーマット <a class="header-anchor" href="#📝-テンプレート-csv-フォーマット" aria-label="Permalink to &quot;📝 テンプレート CSV フォーマット&quot;">​</a></h2><p>テンプレートで取り込む場合は、以下の形式で CSV を用意してください。</p><h3 id="csv-の条件" tabindex="-1">CSV の条件 <a class="header-anchor" href="#csv-の条件" aria-label="Permalink to &quot;CSV の条件&quot;">​</a></h3><ol><li><strong>文字コード</strong>：UTF-8 または GBK</li><li><strong>区切り</strong>：カンマ <code>,</code></li><li><strong>ヘッダー</strong>：1 行目はヘッダー必須</li></ol><h3 id="標準フォーマット例" tabindex="-1">標準フォーマット例 <a class="header-anchor" href="#標準フォーマット例" aria-label="Permalink to &quot;標準フォーマット例&quot;">​</a></h3><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">日期,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">类型,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">金额,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">分类,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">账户,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">备注,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">标签</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-01,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">支出,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">100.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">餐饮,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">现金,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">午餐,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">工作餐</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2024-01-02,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">收入,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">5000.00,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">工资,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">银行卡,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">月薪,</span></span></code></pre></div><h3 id="フィールド説明" tabindex="-1">フィールド説明 <a class="header-anchor" href="#フィールド説明" aria-label="Permalink to &quot;フィールド説明&quot;">​</a></h3><table tabindex="0"><thead><tr><th>フィールド</th><th>説明</th><th>必須</th><th>例</th></tr></thead><tbody><tr><td>取引日</td><td>明細の日付（形式：<code>yyyy/MM/dd</code>）</td><td>✅</td><td>2026/01/01</td></tr><tr><td>収支種別</td><td>支出 / 収入</td><td>✅</td><td>支出 / 收入</td></tr><tr><td>親カテゴリ</td><td>1 階層目のカテゴリ名</td><td>✅</td><td>伙食</td></tr><tr><td>子カテゴリ</td><td>2 階層目のカテゴリ名（親の配下）</td><td>✅</td><td>早餐</td></tr><tr><td>入金額</td><td>収入の場合に使用する金額</td><td>✅</td><td>100.00</td></tr><tr><td>出金額</td><td>支出の場合に使用する金額</td><td>✅</td><td>15</td></tr><tr><td>口座</td><td>口座名（Koala 内の既存口座名を推奨）</td><td>✅</td><td>默认账户</td></tr><tr><td>メモ</td><td>明細メモ</td><td>❌</td><td>午餐</td></tr><tr><td>タグ</td><td>タグ名（複数はカンマ区切り）</td><td>❌</td><td>工作餐,聚餐</td></tr></tbody></table><h3 id="テンプレートをダウンロード" tabindex="-1">テンプレートをダウンロード <a class="header-anchor" href="#テンプレートをダウンロード" aria-label="Permalink to &quot;テンプレートをダウンロード&quot;">​</a></h3><ol><li>インポート画面で <strong>「テンプレートをダウンロード」</strong> をタップ</li><li>サンプル CSV がダウンロードされます</li><li>その形式を参考にご自身のデータを作成してください</li></ol><hr><h2 id="⚠️-注意事項" tabindex="-1">⚠️ 注意事項 <a class="header-anchor" href="#⚠️-注意事項" aria-label="Permalink to &quot;⚠️ 注意事項&quot;">​</a></h2><h3 id="_1-データ形式" tabindex="-1">1. データ形式 <a class="header-anchor" href="#_1-データ形式" aria-label="Permalink to &quot;1. データ形式&quot;">​</a></h3><ul><li><strong>日付</strong>：<code>YYYY/MM/DD</code>（例：<code>2026/01/01</code>）</li><li><strong>金額</strong>：数値（小数可、例：<code>100.00</code>）</li><li><strong>収支種別</strong>：<code>支出</code> または <code>收入</code></li><li><strong>カテゴリ/口座</strong>：未作成の場合、インポート時に自動作成されることがあります</li></ul><h3 id="_2-取り込み前の検証" tabindex="-1">2. 取り込み前の検証 <a class="header-anchor" href="#_2-取り込み前の検証" aria-label="Permalink to &quot;2. 取り込み前の検証&quot;">​</a></h3><p>インポート前に、Koala がデータを自動チェックします。</p><ul><li>✅ 有効：取り込み可能</li><li>⚠️ 無効：形式不正のため修正が必要</li><li>❌ スキップ：無効をスキップして有効のみ取り込み可能</li></ul><h3 id="_3-重複データ" tabindex="-1">3. 重複データ <a class="header-anchor" href="#_3-重複データ" aria-label="Permalink to &quot;3. 重複データ&quot;">​</a></h3><ul><li>取り込み前に重複がないか確認することをおすすめします</li></ul><h3 id="_4-大量データ" tabindex="-1">4. 大量データ <a class="header-anchor" href="#_4-大量データ" aria-label="Permalink to &quot;4. 大量データ&quot;">​</a></h3><ul><li>1,000 件以上など大量の場合は分割して取り込み推奨</li><li>取り込み中はアプリを前面にしておいてください</li><li>取り込み後、必要に応じて手動同期を実行してください</li></ul><hr><h2 id="🔧-よくある質問" tabindex="-1">🔧 よくある質問 <a class="header-anchor" href="#🔧-よくある質問" aria-label="Permalink to &quot;🔧 よくある質問&quot;">​</a></h2><h3 id="q1-解析に失敗します" tabindex="-1">Q1：解析に失敗します <a class="header-anchor" href="#q1-解析に失敗します" aria-label="Permalink to &quot;Q1：解析に失敗します&quot;">​</a></h3><p>以下を確認してください。</p><ol><li>ファイル形式（CSV / Excel）が正しい</li><li>インポート元の選択が正しい</li><li>ファイルが破損していない</li><li>文字コードが適切（UTF-8 推奨）</li></ol><h3 id="q2-取り込まれたデータが一部欠けています" tabindex="-1">Q2：取り込まれたデータが一部欠けています <a class="header-anchor" href="#q2-取り込まれたデータが一部欠けています" aria-label="Permalink to &quot;Q2：取り込まれたデータが一部欠けています&quot;">​</a></h3><p>考えられる原因：</p><ol><li>形式不正の行がスキップされた</li><li>カテゴリ/口座が存在しない（作成が必要）</li><li>プレビュー画面で「無効な明細」を確認してください</li></ol><h3 id="q3-画像はインポートできますか" tabindex="-1">Q3：画像はインポートできますか？ <a class="header-anchor" href="#q3-画像はインポートできますか" aria-label="Permalink to &quot;Q3：画像はインポートできますか？&quot;">​</a></h3><p>現時点では対応していません。</p><h3 id="q4-インポート後に修正できますか" tabindex="-1">Q4：インポート後に修正できますか？ <a class="header-anchor" href="#q4-インポート後に修正できますか" aria-label="Permalink to &quot;Q4：インポート後に修正できますか？&quot;">​</a></h3><p>可能です。取り込み後は明細一覧から編集・削除できます。</p><h3 id="q5-複数ファイルをまとめて取り込めますか" tabindex="-1">Q5：複数ファイルをまとめて取り込めますか？ <a class="header-anchor" href="#q5-複数ファイルをまとめて取り込めますか" aria-label="Permalink to &quot;Q5：複数ファイルをまとめて取り込めますか？&quot;">​</a></h3><p>現時点では 1 回につき 1 ファイルのみです。複数ある場合は 1 つずつ取り込んでください。</p><hr><h2 id="📚-関連ガイド" tabindex="-1">📚 関連ガイド <a class="header-anchor" href="#📚-関連ガイド" aria-label="Permalink to &quot;📚 関連ガイド&quot;">​</a></h2><ul><li><a href="./02-wechat-bill-import-guide">WeChat 明細インポート</a></li><li><a href="./03-alipay-bill-import-guide">Alipay 明細インポート</a></li><li><a href="./04-multi-ledger-guide">複数帳簿（多帳本）</a></li></ul><hr><p><strong>最終更新</strong>：2026 年 1 月</p>`,71)])])}const k=i(r,[["render",s]]);export{u as __pageData,k as default};
